#include <vector>
#include <algorithm>

class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        int totalOnes = 0, maxBits = 0;
        for (int x : nums) {
            totalOnes += __builtin_popcount(x);
            int bits = 0;
            int temp = x;
            while (temp > 1) {
                bits++;
                temp >>= 1;
            }
            maxBits = std::max(maxBits, bits);
        }
        return totalOnes + maxBits;
    }
};

class Solution {
    public int minOperations(int[] nums) {
        int totalOnes = 0, maxBits = 0;
        for (int x : nums) {
            totalOnes += Integer.bitCount(x);
            int bits = 0;
            int temp = x;
            while (temp > 1) {
                bits++;
                temp >>= 1;
            }
            maxBits = Math.max(maxBits, bits);
        }
        return totalOnes + maxBits;
    }
}

var minOperations = function(nums) {
    let totalOnes = 0, maxBits = 0;
    for (let x of nums) {
        let temp = x;
        let bits = 0;
        while (temp > 0) {
            totalOnes += (temp & 1);
            if (temp > 1) bits++;
            temp >>= 1;
        }
        maxBits = Math.max(maxBits, bits);
    }
    return totalOnes + maxBits;
};
